// Reconciliation cadence: on Ticker's clock (this schedule), tell Ledger to
// compare what Cavi believes the ERP holds against what it actually holds.
// The interval above is the drift-detection window (PRD NFR4) — tighten it
// with the design partner. Advisory only: the pass that this triggers never
// corrects anything; drift is surfaced to a human via Beacon.
return {
  json: {
    subject: 'ticker.reconciliation.due',
    schema_version: 1,
    source: 'n8n:reconciliation-cadence',
    correlation_id: null,
    payload: {
      tenant_id: $env.CAVI_RECONCILE_TENANT || 'tenant-acme',
      erp_platform: 'netsuite',
      scope: $env.CAVI_RECONCILE_SCOPE || 'journalEntry',
      due_at: new Date().toISOString(),
    },
  },
};
